import React from 'react';
import './Pages.css';

function About({ lang }) {
  return (
    <div className="page">
      {/* Тег h1 — «Кофейня «Уютный уголок» */}
      <h1>
        {lang === 'ru'
          ? 'Кофейня «Coffee Time»'
          : 'Coffee shop «Coffee Time»'}
      </h1>

      {/* Фото основателя кофейни */}
      <div className="founder-photo">
        <img
          src="/founder.jpg"
          alt={lang === 'ru' ? 'Основатель кофейни' : 'Coffee shop founder'}
          className="founder-image"
        />
      </div>

      {/* Тег p — «Мы варим лучший кофе с 2010 года» */}
      <p>
        {lang === 'ru'
          ? 'Мы варим лучший кофе с 2010 года'
          : 'We have been brewing the best coffee since 2010'}
      </p>

      {/* Тег p — «Наши бариста – профессиональные обжарщики зёрен» */}
      <p>
        {lang === 'ru'
          ? 'Наши бариста – профессиональные обжарщики зёрен'
          : 'Our baristas are professional coffee roasters'}
      </p>

      {/* Тег p — «Только свежемолотый кофе и натуральные ингредиенты» */}
      <p>
        {lang === 'ru'
          ? 'Только свежемолотый кофе и натуральные ингредиенты'
          : 'Only freshly ground coffee and natural ingredients'}
      </p>

      {/* Тег p — «Мы закупаем зёрна напрямую с плантаций Бразилии, Колумбии и Эфиопии» */}
      <p>
        {lang === 'ru'
          ? 'Мы закупаем зёрна напрямую с плантаций Бразилии, Колумбии и Эфиопии'
          : 'We buy beans directly from plantations in Brazil, Colombia and Ethiopia'}
      </p>
    </div>
  );
}

export default About;
